api_dir = Path('scoring/results/plan001/individual_scores')

api_asr = {}
for mid in API_MODELS:
    api_asr[mid] = {}
    for atk in ATTACKS:
        asrs = []
        for ds in DATASETS:
            fp = api_dir / f'{mid}__{ds}__{atk}.json'
            if fp.exists():
                with open(fp) as f:
                    d = json.load(f)
                asrs.append(d.get('asr', 0))
        api_asr[mid][atk] = sum(asrs)/len(asrs) if asrs else None

# ── Local models: compute ASR from checkpoint files ──
LOCAL_MODELS = ['qwen2.5-72b','llama3.1-70b','mistral-large','qwen2.5-32b','qwen2.5-14b','llama3.1-8b']

