            attacked = ckpt.get('attacked_scores',{}).get(ds,{}).get(atk,{}).get(mid,[])
            if clean and attacked:
                asr_val = compute_asr_from_scores(clean, attacked)
                asrs.append(asr_val)
        local_asr[mid][atk] = sum(asrs)/len(asrs) if asrs else None

